insert into question_pyq_meta (question_id, appear_count, years, exams, verified)
select id, appear_count, coalesce((select array_agg(v::int) from jsonb_array_elements_text(years) as v), '{}')::int[], coalesce((select array_agg(v) from jsonb_array_elements_text(exams) as v), '{}')::text[], verified
from jsonb_to_recordset($json$[{"id":"che-st-176","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"One mole of $\\mathrm{H_2}$ is mixed with one mole of $\\mathrm{O_2}$ and sparked to form water. The reactant that is used up completely is","options":["oxygen","hydrogen","both equally","neither"],"answer_index":1,"explanation":"Water needs H$_2$ : O$_2$ = 2 : 1, so 1 mol H$_2$ is finished while 0.5 mol O$_2$ is still unused.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-177","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A flask is charged with 1 mol of $\\mathrm{N_2}$ and 1 mol of $\\mathrm{H_2}$ for the Haber reaction. Ammonia production is limited by","options":["nitrogen","hydrogen","both together","the catalyst only"],"answer_index":1,"explanation":"The 1 : 3 nitrogen-to-hydrogen requirement means 1 mol H$_2$ is exhausted long before the nitrogen.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-178","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Two moles of carbon are heated with one mole of oxygen to give only $\\mathrm{CO_2}$. The reagent that decides the amount of $\\mathrm{CO_2}$ is","options":["carbon","oxygen","neither; both finish together","the vessel volume"],"answer_index":1,"explanation":"Each mole of $\\mathrm{CO_2}$ needs 1 mol O$_2$; only 1 mol O$_2$ is supplied, so oxygen limits.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-179","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Equal molar amounts of $\\mathrm{H_2}$ and $\\mathrm{Cl_2}$ are allowed to form HCl. At the end of the reaction","options":["hydrogen remains unused","chlorine remains unused","both gases are completely consumed","no HCl forms"],"answer_index":2,"explanation":"$\\mathrm{H_2} + \\mathrm{Cl_2} \\rightarrow 2\\mathrm{HCl}$ uses the two gases in a 1 : 1 mole ratio.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-180","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Three moles of magnesium ribbon are burnt in one mole of oxygen. Formation of $\\mathrm{MgO}$ is limited by","options":["magnesium","oxygen","both equally","air moisture"],"answer_index":1,"explanation":"$2\\mathrm{Mg} + \\mathrm{O_2}$ needs Mg : O$_2$ = 2 : 1; 1 mol O$_2$ can consume only 2 mol Mg, so oxygen limits.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-181","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The quantity of product that can form in a given run is fixed by","options":["the reagent present in greater mass, always","the reagent that is consumed first","the reagent with the larger molar mass","whichever reagent is added last"],"answer_index":1,"explanation":"The limiting reagent is used up first and therefore caps the product.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-182","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"If a balanced equation is 1 : 1 and the two reactants are supplied in unequal moles, the leftover substance is","options":["always the product","the reactant that was supplied in smaller moles","the reactant that was supplied in larger moles","a catalyst"],"answer_index":2,"explanation":"The reactant present in fewer moles is limiting; the one in larger moles is excess and remains.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-183","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"One mole of sulphur is burnt in two moles of oxygen to give only $\\mathrm{SO_2}$. The unused oxygen at the end is","options":["0 mol","1 mol","2 mol","0.5 mol"],"answer_index":1,"explanation":"$\\mathrm{S} + \\mathrm{O_2} \\rightarrow \\mathrm{SO_2}$ uses 1 mol O$_2$, leaving 1 mol unused.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-184","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Aluminium and chlorine are mixed as 2 mol Al + 3 mol $\\mathrm{Cl_2}$ to form $\\mathrm{AlCl_3}$ ($2\\mathrm{Al} + 3\\mathrm{Cl_2} \\rightarrow 2\\mathrm{AlCl_3}$). The limiting reagent is","options":["aluminium only","chlorine only","neither; the mixture is stoichiometric","impossible to decide"],"answer_index":2,"explanation":"The supplied amounts match the 2 : 3 coefficients, so both finish together.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-185","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Four grams of hydrogen (M = 2) are sparked with 32 g of oxygen (M = 32) to form water. The mass of water that can form is","options":["18 g","36 g","16 g","4 g"],"answer_index":1,"explanation":"2 mol H$_2$ and 1 mol O$_2$ match $2\\mathrm{H_2} + \\mathrm{O_2}$; both are used and give 2 mol (36 g) of water.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
    id text,
